(function(){
  function parseUrls(text){ return {value: String(text||'').split(/[\r\n]+/).map(function(s){return s.trim();}).filter(function(s){return /^https?:\/\//i.test(s);})}; }
  function summarize(results){ var up=0,down=0,lat=0; for(var i=0;i<results.length;i++){ if(results[i].ok){up++; if(results[i].ms)lat+=results[i].ms;} else down++; } return {value:{up:up, down:down, avg: up? Math.round(lat/up):0}}; }
  var API={parseUrls:parseUrls, summarize:summarize};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__UptimeForge__=API;
})();
